(function(){'use strict';const vscode = acquireVsCodeApi();let currentTab = 'home';document.addEventListener('DOMContentLoaded',initializeWebview);function initializeWebview(){setupTabNavigation();setupCommandButtons();setupKeyboardNavigation();const state = vscode.getState();if(state && state.currentTab){switchToTab(state.currentTab)}}function setupTabNavigation(){const tabButtons = document.querySelectorAll('.tab-button');tabButtons.forEach(button =>{button.addEventListener('click',handleTabClick)})}function handleTabClick(event){const tabId = event.currentTarget.id.replace('-tab','');switchToTab(tabId);vscode.postMessage({type:'navigate',tab:tabId})}function switchToTab(tabId){const tabPanels = document.querySelectorAll('.tab-panel');tabPanels.forEach(panel =>{panel.classList.remove('active');panel.setAttribute('aria-hidden','!0')});const tabButtons = document.querySelectorAll('.tab-button');tabButtons.forEach(button =>{button.classList.remove('active');button.setAttribute('aria-selected','!1');button.setAttribute('tabindex','-1')});const targetPanel = document.getElementById(`${tabId}-panel`);if(targetPanel){targetPanel.classList.add('active');targetPanel.setAttribute('aria-hidden','!1')}const targetButton = document.getElementById(`${tabId}-tab`);if(targetButton){targetButton.classList.add('active');targetButton.setAttribute('aria-selected','!0');targetButton.setAttribute('tabindex','0');targetButton.focus()}currentTab = tabId;vscode.setState({currentTab:tabId});}function setupCommandButtons(){const commandButtons = document.querySelectorAll('[data-command]');commandButtons.forEach(button =>{button.addEventListener('click',handleCommandClick)})}function handleCommandClick(event){event.preventDefault();const command = event.currentTarget.getAttribute('data-command');if(!command){console.warn('No command specified for button');return}const originalText = event.currentTarget.textContent;event.currentTarget.textContent = 'Executing...';event.currentTarget.disabled = !0;vscode.postMessage({type:'executeCommand',command:command});setTimeout(()=>{event.currentTarget.textContent = originalText;event.currentTarget.disabled = !1},1000);}function setupKeyboardNavigation(){document.addEventListener('keydown',handleKeyDown)}function handleKeyDown(event){if(event.target.classList.contains('tab-button')){const tabButtons = Array.from(document.querySelectorAll('.tab-button'));const currentIndex = tabButtons.indexOf(event.target);switch(event.key){case 'ArrowLeft':case 'ArrowUp':event.preventDefault();const prevIndex = currentIndex > 0 ? currentIndex - 1:tabButtons.length - 1;tabButtons[prevIndex].click();break;case 'ArrowRight':case 'ArrowDown':event.preventDefault();const nextIndex = currentIndex < tabButtons.length - 1 ? currentIndex + 1:0;tabButtons[nextIndex].click();break;case 'Home':event.preventDefault();tabButtons[0].click();break;case 'End':event.preventDefault();tabButtons[tabButtons.length - 1].click();break;case 'Enter':case ' ':event.preventDefault();event.target.click();break}}if(event.ctrlKey || event.metaKey){switch(event.key){case '1':event.preventDefault();switchToTab('home');break;case '2':event.preventDefault();switchToTab('database');break;case '3':event.preventDefault();switchToTab('analysis');break;case '4':event.preventDefault();switchToTab('settings');break}}}window.addEventListener('message',event =>{const message = event.data;switch(message.type){case 'switchTab':switchToTab(message.tab);break;case 'showNotification':showNotification(message.text,message.level || 'info');break;case 'updateStats':updateStatistics(message.stats);break;default:}});function showNotification(text,level = 'info'){vscode.postMessage({type:level === 'error' ? 'showError':'showInfo',text:text})}function updateStatistics(stats){if(!stats)return;const statElements ={commands:document.querySelector('.stat-card:nth-child(1).stat-number'),databases:document.querySelector('.stat-card:nth-child(2).stat-number'),tools:document.querySelector('.stat-card:nth-child(3).stat-number')};if(stats.commands && statElements.commands){statElements.commands.textContent = stats.commands}if(stats.databases && statElements.databases){statElements.databases.textContent = stats.databases}if(stats.tools && statElements.tools){statElements.tools.textContent = stats.tools}}function debounce(func,wait){let timeout;return function executedFunction(...args){const later =()=>{clearTimeout(timeout);func(...args)};clearTimeout(timeout);timeout = setTimeout(later,wait)}}const handleResize = debounce(()=>{},250);window.addEventListener('resize',handleResize);if(typeof window !== 'void 0' && window.location.hostname === 'localhost'){window.biomniPanel ={switchToTab,currentTab:()=> currentTab,showNotification}}})()